import React from 'react';

const Contact = () => {
  const contactMethods = [
    {
      icon: 'fas fa-envelope',
      title: 'Email',
      value: 'leeans222@gmail.com',
      link: 'mailto:leeans222@gmail.com'
    },
    {
      icon: 'fab fa-linkedin',
      title: 'LinkedIn',
      value: 'linkedin.com/in/an222',
      link: 'https://linkedin.com/in/an222'
    },
    {
      icon: 'fab fa-github',
      title: 'GitHub',
      value: 'github.com/An022',
      link: 'https://github.com/An022'
    }
  ];

  const handleContactClick = (link) => {
    if (link.startsWith('mailto:')) {
      window.location.href = link;
    } else {
      window.open(link, '_blank', 'noopener,noreferrer');
    }
  };

  return (
    <section id="contact" className="py-16 bg-gradient-to-br from-primary via-secondary to-accent">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center text-white mb-12">
          <h2 className="text-4xl font-bold mb-4">Ready to Start a New Sprint?</h2>
          <p className="text-xl max-w-3xl mx-auto mb-8">
            Let's collaborate and build something amazing together. I'm always excited to work on new challenges and learn from great teams.
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {contactMethods.map((method, index) => (
            <div 
              key={index} 
              className="text-center cursor-pointer transform hover:scale-105 transition-transform duration-300"
              onClick={() => handleContactClick(method.link)}
            >
              <div className="w-16 h-16 bg-accent/20 rounded-2xl flex items-center justify-center mx-auto mb-4">
                <i className={`${method.icon} text-white text-2xl`}></i>
              </div>
              <h3 className="text-xl font-bold text-white mb-2">{method.title}</h3>
              <p className="text-white/80">{method.value}</p>
            </div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default Contact;
